<?php

declare(strict_types=1);

use ChangeCouncil\Petitions\DeliveryResult;
use ChangeCouncil\Tests\Support\TestApp;

/*
 * The petition text is the wire format of design section 9.2, generated by the
 * ledger and SENT BY AN AGENT (the clerk). The ledger never calls Genie.
 */

beforeEach(function (): void {
    councilApp();
    consumer('moic@moic-suite', ['particle-academy/prism'], extra: ['census_at' => \Illuminate\Support\Carbon::parse('2026-10-20')]);
});

test('the petition text follows the v1 format exactly', function (): void {
    $change = propose();
    $petition = petitionFor($change, 'moic@moic-suite');
    $text = TestApp::$transport->queued[0]['text'];
    $lines = explode("\n", $text);

    expect(array_slice($lines, 0, 10))->toBe([
        'COUNCIL-PETITION v1',
        'change: CC-fancy-0001',
        'round: 1',
        'nonce: '.$petition->nonce,
        'digest: '.$change->currentRound()->approach_digest,
        'reply-by: 2026-10-30T12:00:00Z',
        'tier: required',
        'why-you: you declared particle-academy/prism * (census 2026-10-20)',
        'lab: https://lab.example.test/council/changes/CC-fancy-0001',
        '----',
    ])
        ->and($text)->toContain("Reply with a message whose FIRST line is `COUNCIL-REPLY v1`, followed by ONE\nJSON object, exactly as below. Nothing else in the message is read.")
        ->and($text)->toContain('{"change":"CC-fancy-0001","round":1,"nonce":"'.$petition->nonce.'",')
        ->and($text)->toContain('"verdict":"approve|conflict|abstain"')
        ->and($petition->nonce)->toMatch('/^[0-9a-f]{16}$/')
        ->and($change->currentRound()->approach_digest)->toMatch('/^sha256:[0-9a-f]{64}$/');
});

test('the summary between the rules carries packages, classes, the approach and the evidence links', function (): void {
    propose();
    $text = TestApp::$transport->queued[0]['text'];
    $summary = explode("----\n", $text)[1];

    expect($summary)->toContain('particle-academy/prism 0.139.0 -> 0.140.0')
        ->and($summary)->toContain('declared-breaking')
        ->and($summary)->toContain('Consumers wrap their callbacks.')
        ->and($summary)->toContain('commit: abc1234');
});

test('council:petitions lists the outgoing petitions for the clerk, and --mark-sent records a result', function (): void {
    $change = propose();
    $petition = petitionFor($change, 'moic@moic-suite');

    $listed = json_decode(runCommand('council:petitions', ['--json' => true]), true);
    expect($listed)->toHaveCount(1)
        ->and($listed[0])->toMatchArray(['petition' => $petition->id, 'to' => 'moic@moic-suite'])
        ->and($listed[0]['text'])->toStartWith('COUNCIL-PETITION v1');

    runCommand('council:petitions', ['--mark-sent' => (string) $petition->id, '--result' => '{"result":{"content":[{"type":"text","text":"Sent.\n{\"ok\":true,\"id\":\"m-1\"}"}]}}']);

    expect($petition->fresh()->delivery)->toBe('sent')
        ->and(json_decode(runCommand('council:petitions', ['--json' => true]), true))->toBe([]);
});

test('a delivery verdict is read at all three refusal depths; anything unconfirmed is undelivered', function (string $raw, string $delivery): void {
    expect(DeliveryResult::parse($raw)->delivery)->toBe($delivery);
})->with([
    'ok true after prose' => ['{"result":{"content":[{"type":"text","text":"Delivered.\n{\"ok\":true}"}]}}', 'sent'],
    'depth 1: JSON-RPC error' => ['{"error":{"code":-32000,"message":"boom"}}', 'undelivered'],
    'depth 2: isError' => ['{"result":{"isError":true,"content":[{"type":"text","text":"{\"ok\":true}"}]}}', 'undelivered'],
    'depth 3: ok false after prose' => ['{"result":{"content":[{"type":"text","text":"Use the tag format {provider}:{name}.\n{\"ok\":false,\"error\":\"No agent matches x\"}"}]}}', 'undelivered'],
    'prose with braces and no verdict' => ['{"result":{"content":[{"type":"text","text":"The format is {provider}:{name}"}]}}', 'undelivered'],
    'not JSON at all' => ['sent it, trust me', 'undelivered'],
    'permission denied' => ['{"result":{"content":[{"type":"text","text":"{\"ok\":false,\"error\":\"permission denied: agent is not reachable\"}"}]}}', 'unreachable'],
]);
